const here = position();
if (inventory_count('cobblestone') < 3) {
  const took = await take_from_depot('cobblestone');
  if (!took.ok) {
    return { done: false, detail: 'there is nothing at the depot' };
  }
}
for (let i = 1; i <= 3; i++) {
  await place('cobblestone', here.x, here.y + i, here.z);
}
return { done: true, detail: 'raised a three block pillar' };
